<script lang="ts">let { options = [], value = $bindable('') }: { options: { value: string; label: string }[]; value?: string } = $props();</script><div role="tablist" class="seg">{#each options as o}<button role="tab" aria-selected={value === o.value} class:active={value === o.value} onclick={() => (value = o.value)}>{o.label}</button>{/each}</div><style>.seg{display:flex;background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius);padding:2px;gap:2px}.seg button{background:transparent;border:none;color:var(--text-1);padding:var(--space-2) var(--space-4);border-radius:var(--radius-sm)}.seg button.active{background:var(--bg-3);color:var(--text-0)}</style>
